class Solution {
    public int minAbsoluteDifference(List<Integer> nums,int x){
        TreeSet<Integer> values=new TreeSet<>();
        int answer=Integer.MAX_VALUE;
        for(int right=x;right<nums.size();right++){
            int value=nums.get(right);
            values.add(nums.get(right-x));
            Integer floor=values.floor(value),ceiling=values.ceiling(value);
            if(floor!=null)answer=Math.min(answer,value-floor);
            if(ceiling!=null)answer=Math.min(answer,ceiling-value);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minAbsoluteDifference(nums:List<Int>,x:Int):Int{
        val values=java.util.TreeSet<Int>();
        var answer=Int.MAX_VALUE;
        for(right in x until nums.size){
            val value=nums[right];
            values.add(nums[right-x]);
            values.floor(value)?.let{
                answer=minOf(answer,value-it)
            };
            values.ceiling(value)?.let{
                answer=minOf(answer,it-value)
            }
        };
        return answer
    }
}

